-- Read-only UTC 1/7/30-day target blocks; exact reference availability and aggregate model scores.
WITH targets AS (SELECT a.dateTime,a.outTemp AS y,CASE WHEN a.dateTime<1577836800 THEN 2019 ELSE 2020 END AS yr,CASE WHEN a.dateTime<1577836800 THEN 1546300800 ELSE 1577836800 END AS yr_start FROM loucka_reconstruction.archive a WHERE a.dateTime>=1546300800 AND a.dateTime<1609459200 AND a.outTemp IS NOT NULL AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes c WHERE c.target_time=a.dateTime AND c.variable='outTemp')), paired AS (SELECT t.*,CASE WHEN r.temperature_c IS NOT NULL AND r.source_resolution='5min' AND r.quality_status='reference_only' THEN 1 ELSE 0 END AS eligible,CASE WHEN r.temperature_c=0 AND t.y>=20 THEN 1 ELSE 0 END AS suspect_zero_hot,r.temperature_c AS ref,(0.7886750170162296+0.9352562666974354*r.temperature_c+-0.20129399741209056*SIN(2*PI()*MOD(t.dateTime,86400)/86400)+-0.09305546547425936*COS(2*PI()*MOD(t.dateTime,86400)/86400)+-0.3075224035244028*SIN(2*PI()*(CASE WHEN t.dateTime<1577836800 THEN t.dateTime-1546300800 ELSE t.dateTime-1577836800 END)/(CASE WHEN t.dateTime>=1577836800 THEN 31622400 ELSE 31536000 END))+-1.496803043901965*COS(2*PI()*(CASE WHEN t.dateTime<1577836800 THEN t.dateTime-1546300800 ELSE t.dateTime-1577836800 END)/(CASE WHEN t.dateTime>=1577836800 THEN 31622400 ELSE 31536000 END))) AS model FROM targets t LEFT JOIN loucka_reconstruction.reference_observations r ON r.station_id='luhamet_sehradice' AND r.observed_at_utc=t.dateTime), windows AS (SELECT 86400 AS block_s,'1d' AS block_type,dateTime,yr,yr_start,y,eligible,suspect_zero_hot,ref,model FROM paired UNION ALL SELECT 604800,'7d',dateTime,yr,yr_start,y,eligible,suspect_zero_hot,ref,model FROM paired UNION ALL SELECT 2592000,'30d',dateTime,yr,yr_start,y,eligible,suspect_zero_hot,ref,model FROM paired) SELECT block_type,yr,FLOOR((dateTime-yr_start)/block_s) AS block_index,MIN(dateTime) AS first_target_utc,MAX(dateTime) AS last_target_utc,COUNT(*) AS target_n,SUM(eligible) AS eligible_n,SUM(suspect_zero_hot) AS zero_hot_n,SUM(CASE WHEN eligible=1 THEN ABS(ref-y) ELSE 0 END) AS m0_abs,SUM(CASE WHEN eligible=1 THEN POW(ref-y,2) ELSE 0 END) AS m0_sq,SUM(CASE WHEN eligible=1 THEN ref-y ELSE 0 END) AS m0_err,SUM(CASE WHEN eligible=1 THEN ABS(model-y) ELSE 0 END) AS ols_abs,SUM(CASE WHEN eligible=1 THEN POW(model-y,2) ELSE 0 END) AS ols_sq,SUM(CASE WHEN eligible=1 THEN model-y ELSE 0 END) AS ols_err,SUM(CASE WHEN eligible=1 AND suspect_zero_hot=0 THEN ABS(ref-y) ELSE 0 END) AS m0_abs_nonflag,SUM(CASE WHEN eligible=1 AND suspect_zero_hot=0 THEN POW(ref-y,2) ELSE 0 END) AS m0_sq_nonflag,SUM(CASE WHEN eligible=1 AND suspect_zero_hot=0 THEN ABS(model-y) ELSE 0 END) AS ols_abs_nonflag,SUM(CASE WHEN eligible=1 AND suspect_zero_hot=0 THEN POW(model-y,2) ELSE 0 END) AS ols_sq_nonflag,SUM(CASE WHEN eligible=1 AND y<=0 THEN 1 ELSE 0 END) AS freeze_n,SUM(CASE WHEN eligible=1 AND y<=0 THEN ABS(ref-y) ELSE 0 END) AS m0_abs_freeze,SUM(CASE WHEN eligible=1 AND y<=0 THEN POW(ref-y,2) ELSE 0 END) AS m0_sq_freeze,SUM(CASE WHEN eligible=1 AND y<=0 THEN ABS(model-y) ELSE 0 END) AS ols_abs_freeze,SUM(CASE WHEN eligible=1 AND y<=0 THEN POW(model-y,2) ELSE 0 END) AS ols_sq_freeze FROM windows GROUP BY block_type,yr,block_index ORDER BY block_type,yr,block_index;
